-- =====================================================================
-- НОРМАЛИЗАЦИЯ СТРУКТУРЫ БД (1НФ, 2НФ, 3НФ)
-- =====================================================================
-- Шаг 1. Повторяющиеся сведения и группы столбцов о разных объектах
--   В исходной таблице книг (book_list) в одной строке хранились сведения
--   о трёх разных объектах — книге, авторе и жанре:
--   • author — одни и те же имена повторялись в строках (100 авторов на 1000 книг),
--     а у части книг есть соавторы, которых в одну ячейку не записать;
--   • genre — 10 значений повторялись в 1000 строках, у части книг несколько жанров.
--   В выдачах (loans) часть столбцов вычислялась из других столбцов:
--   • status однозначно определяется датой возврата (NULL = книга на руках);
--   В связи «книга – автор» порядок автора дублировал его роль.
--
-- Шаг 2. Сущности и распределение полей
--   book_list     — книга: название, год издания, доступность
--   authors       — автор: имя, фамилия
--   genres        — жанр: название
--   book_authors  — кто написал книгу: книга, автор, роль (автор / соавтор)
--   book_genres   — к каким жанрам относится книга: книга, жанр, основной ли
--   clients       — читатель: имя, фамилия, телефон, возрастная группа, дата регистрации
--   loans         — взятие книги читателем (выдача): читатель, книга, даты, просрочка
--   book_ratings  — оценка: читатель, книга, балл, комментарий, дата
--   (book_catalog, book_info, author_books, client_rating, book_rating — это
--    представления: они ничего не хранят, а собирают данные запросом)
--
-- Шаг 3. Первичные ключи
--   book_list: book_id            authors: author_id        genres: genre_id
--   clients: client_id            loans: loan_id
--   book_authors: (book_id, author_id)    book_genres: (book_id, genre_id)
--   book_ratings: rating_id (плюс UNIQUE (client_id, book_id) — одна оценка на пару)
--
-- Шаг 4. Проверка по правилам нормальных форм
--   1НФ (атомарные значения, нет повторяющихся групп):
--     в каждой ячейке одно значение (в том числе один телефон на читателя): нет списков
--     «Fiction, Romance» и столбцов
--     genre1 / genre2 / co_author; у каждой таблицы есть первичный ключ.
--     Несколько жанров и авторов у книги — это несколько строк в связующих таблицах.
--   2НФ (нет зависимости от части составного ключа):
--     составной ключ только у book_authors и book_genres; role и is_primary
--     описывают пару «книга + автор» / «книга + жанр» целиком, а не одну её часть.
--     В остальных таблицах ключ из одного столбца, поэтому частичных зависимостей нет.
--     В book_ratings комментарий, балл и дата относятся к паре читатель + книга целиком.
--   3НФ (нет зависимости неключевых полей друг от друга):
--     • в book_list имя автора и название жанра раньше зависели от book_id
--       «через» самого автора и жанр — теперь они в своих таблицах;
--     • loans.status — вычисляемый столбец (GENERATED), а не хранимый;
--     • book_authors: удалён author_order, т.к. он повторял role
--       (1 = автор, 2 и больше = соавторы). Единственность основного автора
--       гарантирует частичный уникальный индекс ux_book_authors_main.
--
-- Шаг 5. Какие поля вынесены и почему
--   book_list.author  -> authors + book_authors
--       имя автора дублировалось в сотнях строк (правка имени = правка многих строк),
--       и у 151 книги есть соавторы — в один столбец их не записать (1НФ).
--   book_list.genre   -> genres + book_genres
--       10 значений повторялись в 1000 строках, у 379 книг несколько жанров (1НФ).
--   loans.status    -> вычисляется из return_date (3НФ), в запросах работает как раньше.
--   book_authors.author_order -> удалён: дублировал role (3НФ).
--
-- Что осознанно НЕ разбивали (чтобы не дробить таблицы без смысла):
--   • clients.age_group — 4 допустимых значения, их контролирует CHECK; отдельная
--     таблица из четырёх строк не добавила бы новых сведений о читателе.
--   • book_list.title — название повторяется у разных книг (разные авторы и годы),
--     но ничего не определяет, поэтому зависимостей нет.
--   • book_list.is_available — зависит только от book_id; значение выводится из
--     выдач и обновляется после загрузки (UPDATE ниже), оставлено для удобства.
--   • loans.overdue_days — у возвращённой книги это разница дат, и CHECK следит,
--     чтобы значение с ней совпадало; у 13 книг на руках значение нельзя вычислить
--     без даты отчёта, поэтому столбец хранится.
--   • book_ratings.rating_date — совпадает с датой возврата, но это связь между
--     таблицами, а не внутри одной.
-- Для отчётов остаётся представление book_catalog: книга с основным автором
-- и основным жанром «одной строкой», как раньше выглядела таблица book_list.
-- =====================================================================

PRAGMA foreign_keys = ON;

DROP VIEW IF EXISTS book_genre_details;
DROP VIEW IF EXISTS book_catalog;
DROP VIEW IF EXISTS author_books;
DROP VIEW IF EXISTS book_info;
DROP VIEW IF EXISTS client_rating;
DROP VIEW IF EXISTS book_rating;
DROP INDEX IF EXISTS idx_loans_client;
DROP INDEX IF EXISTS idx_loans_book;
DROP INDEX IF EXISTS idx_ratings_client;
DROP INDEX IF EXISTS idx_ratings_book;
DROP INDEX IF EXISTS ux_book_genres_primary;
DROP INDEX IF EXISTS ux_book_authors_main;
DROP INDEX IF EXISTS idx_book_genres_genre;
DROP INDEX IF EXISTS idx_book_authors_author;
DROP TABLE IF EXISTS book_authors;
DROP TABLE IF EXISTS book_genres;
DROP TABLE IF EXISTS authors;
DROP TABLE IF EXISTS genres;
DROP TABLE IF EXISTS book_ratings;
DROP TABLE IF EXISTS loans;
DROP TABLE IF EXISTS clients;
DROP TABLE IF EXISTS book_list;

-- Книга. Автор и жанр вынесены в authors / genres (см. раздел «Нормализация»).
CREATE TABLE book_list (
    book_id INTEGER PRIMARY KEY,
    title TEXT NOT NULL,
    publication_year INTEGER CHECK (publication_year BETWEEN 1400 AND 2100),
    is_available INTEGER NOT NULL DEFAULT 1 CHECK (is_available IN (0, 1))
);

CREATE TABLE clients (
    client_id INTEGER PRIMARY KEY,
    first_name TEXT NOT NULL,
    last_name TEXT NOT NULL,
    -- Телефон (США, +1). Номера вымышленные: диапазон 555-0100…555-0199 в США
    -- зарезервирован для вымышленных номеров, реальных абонентов за ними нет.
    phone TEXT NOT NULL UNIQUE
        CHECK (phone GLOB '+1 ([0-9][0-9][0-9]) 555-01[0-9][0-9]'),
    age_group TEXT NOT NULL CHECK (age_group IN ('adult', 'child', 'teen', 'senior')),
    registration_date DATE NOT NULL
);

-- Выдачи книг читателям (с внешними ключами).
-- status не хранится: он однозначно следует из return_date (NULL = книга на руках),
-- поэтому это вычисляемый столбец (3НФ).
CREATE TABLE loans (
    loan_id INTEGER PRIMARY KEY,
    client_id INTEGER NOT NULL,
    book_id INTEGER NOT NULL,
    checkout_date DATE NOT NULL,
    due_date DATE NOT NULL,
    return_date DATE,
    status TEXT GENERATED ALWAYS AS
        (CASE WHEN return_date IS NULL THEN 'checked_out' ELSE 'returned' END) VIRTUAL,
    overdue_days INTEGER NOT NULL DEFAULT 0 CHECK (overdue_days >= 0),
    FOREIGN KEY (client_id) REFERENCES clients(client_id),
    FOREIGN KEY (book_id) REFERENCES book_list(book_id),
    CHECK (due_date >= checkout_date),
    CHECK (return_date IS NULL OR return_date >= checkout_date),
    -- у возвращённой книги просрочка = дни между сроком и возвратом (не меньше 0).
    -- У книги на руках значение нельзя вывести без даты отчёта, поэтому оно хранится как есть.
    CHECK (return_date IS NULL
           OR overdue_days = MAX(0, CAST(julianday(return_date) - julianday(due_date) AS INTEGER)))
);

-- Индексы по внешним ключам (ускоряют JOIN и проверку связей)
CREATE INDEX idx_loans_client  ON loans(client_id);
CREATE INDEX idx_loans_book ON loans(book_id);

-- Оценки книг читателями (шкала 0..10)
CREATE TABLE book_ratings (
    rating_id   INTEGER PRIMARY KEY,
    client_id   INTEGER NOT NULL,
    book_id     INTEGER NOT NULL,
    rating      INTEGER NOT NULL CHECK (rating BETWEEN 0 AND 10),
    comment     TEXT,
    rating_date DATE NOT NULL,
    FOREIGN KEY (client_id) REFERENCES clients(client_id),
    FOREIGN KEY (book_id)   REFERENCES book_list(book_id),
    UNIQUE (client_id, book_id)   -- один читатель оценивает книгу один раз
);

CREATE INDEX idx_ratings_client ON book_ratings(client_id);
CREATE INDEX idx_ratings_book   ON book_ratings(book_id);

-- Справочник жанров
CREATE TABLE genres (
    genre_id   INTEGER PRIMARY KEY,
    genre_name TEXT NOT NULL UNIQUE
);

-- Справочник авторов
CREATE TABLE authors (
    author_id  INTEGER PRIMARY KEY,
    first_name TEXT NOT NULL,
    last_name  TEXT NOT NULL,
    UNIQUE (first_name, last_name)
);

-- Жанры книг: у книги может быть несколько жанров (связь «многие ко многим»)
CREATE TABLE book_genres (
    book_id    INTEGER NOT NULL,
    genre_id   INTEGER NOT NULL,
    is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1)),  -- 1 = основной жанр
    PRIMARY KEY (book_id, genre_id),
    FOREIGN KEY (book_id)  REFERENCES book_list(book_id),
    FOREIGN KEY (genre_id) REFERENCES genres(genre_id)
);

-- Авторы книг: у книги может быть автор и соавтор(ы)
CREATE TABLE book_authors (
    book_id      INTEGER NOT NULL,
    author_id    INTEGER NOT NULL,
    role         TEXT NOT NULL DEFAULT 'author' CHECK (role IN ('author', 'co-author')),
    PRIMARY KEY (book_id, author_id),
    FOREIGN KEY (book_id)   REFERENCES book_list(book_id),
    FOREIGN KEY (author_id) REFERENCES authors(author_id)
);

CREATE INDEX idx_book_genres_genre   ON book_genres(genre_id);
CREATE INDEX idx_book_authors_author ON book_authors(author_id);

-- У каждой книги не больше одного основного жанра и ровно один основной автор
-- (остальные авторы — соавторы). Частичные уникальные индексы это гарантируют.
CREATE UNIQUE INDEX ux_book_genres_primary ON book_genres(book_id) WHERE is_primary = 1;
CREATE UNIQUE INDEX ux_book_authors_main   ON book_authors(book_id) WHERE role = 'author';

