-- Жанры и авторы книг (связи «многие ко многим»)
-- =====================================================================
-- В book_list больше нет столбцов author и genre: они вынесены в справочники.
--   • у книги может быть несколько жанров  -> genres + book_genres;
--   • у книги может быть автор и соавтор(ы) -> authors + book_authors.
-- Основной жанр (is_primary = 1) и основной автор (role = 'author') есть у каждой
-- книги — это данные из исходного Excel. Дополнительные жанры и соавторы
-- подобраны мной (допущение): в исходном Excel у каждой книги один жанр и один автор.

