-- Книга со всеми жанрами и авторами (основной жанр / основной автор — первыми)
CREATE VIEW book_info AS
SELECT b.book_id,
       b.title,
       (SELECT GROUP_CONCAT(name, ', ') FROM (
            SELECT a.first_name || ' ' || a.last_name AS name
            FROM book_authors AS ba JOIN authors a ON a.author_id = ba.author_id
            WHERE ba.book_id = b.book_id
            ORDER BY (ba.role = 'author') DESC, a.last_name, a.first_name)) AS authors,
       (SELECT GROUP_CONCAT(genre_name, ', ') FROM (
            SELECT g.genre_name
            FROM book_genres AS bg JOIN genres g ON g.genre_id = bg.genre_id
            WHERE bg.book_id = b.book_id ORDER BY bg.is_primary DESC, g.genre_name)) AS genres,
       (SELECT COUNT(*) FROM book_genres AS x WHERE x.book_id = b.book_id) AS genres_count,
       b.publication_year
FROM book_list AS b;

-- Какие книги у каких авторов (одна строка = один автор + одна его книга)
CREATE VIEW author_books AS
SELECT a.author_id,
       a.first_name || ' ' || a.last_name AS author,
       ba.role,
       b.book_id,
       b.title
FROM authors      AS a
JOIN book_authors AS ba ON ba.author_id = a.author_id
JOIN book_list    AS b  ON b.book_id    = ba.book_id;

-- Книга «одной строкой»: основной автор и основной жанр (как раньше в book_list).
-- Удобно для отчётов: данные не дублируются, а собираются из справочников.
CREATE VIEW book_catalog AS
SELECT b.book_id,
       b.title,
       a.first_name || ' ' || a.last_name AS author,
       g.genre_name                       AS genre,
       b.publication_year,
       b.is_available
FROM book_list    AS b
JOIN book_authors AS ba ON ba.book_id = b.book_id AND ba.role = 'author'
JOIN authors      AS a  ON a.author_id = ba.author_id
JOIN book_genres  AS bg ON bg.book_id = b.book_id AND bg.is_primary = 1
JOIN genres       AS g  ON g.genre_id = bg.genre_id;

-- Жанры книг с названиями: книга (название + основной автор) и жанр словами,
-- а не только номерами. Таблица book_genres хранит лишь id (3НФ), названия подтягиваются здесь.
CREATE VIEW book_genre_details AS
SELECT bg.book_id,
       b.title,
       a.first_name || ' ' || a.last_name AS author,
       bg.genre_id,
       g.genre_name,
       bg.is_primary,                                  -- 1 = основной жанр, 0 = дополнительный
       CASE WHEN bg.is_primary = 1 THEN 'основной' ELSE 'дополнительный' END AS genre_kind,
       (SELECT COUNT(*) FROM book_genres AS x WHERE x.book_id = bg.book_id) AS genres_in_book
FROM book_genres  AS bg
JOIN book_list    AS b  ON b.book_id   = bg.book_id
JOIN book_authors AS ba ON ba.book_id  = bg.book_id AND ba.role = 'author'
JOIN authors      AS a  ON a.author_id = ba.author_id
JOIN genres       AS g  ON g.genre_id  = bg.genre_id;

