-- =====================================================================
-- Загрузка выдач (2000 записей) сразу в таблицу loans
-- =====================================================================
-- В исходном Excel идентификаторы не совпадают с родительскими таблицами:
-- patron_id = 1..4999 (читателей всего 500), catalog_id = 2..11995 (книг 1000);
-- корректными были только 13 строк. Поэтому при загрузке ID приведены к
-- существующим «циклическим» правилом (в БД столбцы названы client_id и book_id):
