-- Проверка количества загруженных строк
SELECT 'book_list' AS table_name, COUNT(*) AS rows_count FROM book_list
UNION ALL
SELECT 'clients', COUNT(*) FROM clients
UNION ALL
SELECT 'loans', COUNT(*) FROM loans;

-- Книги, которые сейчас на руках, помечаем как недоступные
UPDATE book_list
SET is_available = 0
WHERE book_id IN (SELECT book_id FROM loans WHERE status = 'checked_out');

