-- =====================================================================
-- Рейтинги (в Excel — листы client_rating и book_rating с формулами).
-- В БД это представления (VIEW): они не хранят данные, а считают их
-- заново при каждом запросе, как формулы в Excel.
-- =====================================================================

-- Рейтинг читателей. Формула та же, что в Excel:
-- coefficient (0–10) = 10 × (0,5 × books_taken / максимум books_taken
--                           + 0,5 × (1 − late_share))
-- Разница с Excel: здесь считаем по исправленной таблице loans.
-- В Excel формулы COUNTIF смотрят на исходные patron_id (1..4999),
-- поэтому в рейтинг попали только 163 читателя и максимум 3 книги.
CREATE VIEW client_rating AS
WITH stats AS (
    SELECT client_id                    AS client_id,
           COUNT(*)                     AS books_taken,
           SUM(overdue_days > 0)        AS arrears_count,
           SUM(overdue_days)            AS overdue_days_total
    FROM loans
    GROUP BY client_id
)
SELECT s.client_id,
       c.first_name,
       c.last_name,
       c.age_group,
       c.registration_date,
       s.books_taken,
       s.arrears_count,
       s.overdue_days_total,
       s.books_taken - s.arrears_count                         AS score,
       ROUND(1.0 * s.arrears_count / s.books_taken, 2)         AS late_share,
       ROUND(10 * (0.5 * s.books_taken / (SELECT MAX(books_taken) FROM stats)
                 + 0.5 * (1 - 1.0 * s.arrears_count / s.books_taken)), 1) AS coefficient
FROM stats AS s
JOIN clients AS c ON c.client_id = s.client_id;

-- Рейтинг книг: средняя оценка и число оценок (как лист book_rating)
CREATE VIEW book_rating AS
SELECT b.book_id,
       b.title,
       b.author,
       ROUND(AVG(r.rating), 2) AS avg_rating,
       COUNT(*)                AS ratings_count
FROM book_ratings AS r
JOIN book_catalog AS b ON b.book_id = r.book_id
GROUP BY b.book_id;

-- Проверка рейтингов
SELECT * FROM client_rating ORDER BY coefficient DESC, books_taken DESC LIMIT 10;
SELECT * FROM book_rating   ORDER BY avg_rating DESC, ratings_count DESC LIMIT 10;


-- =====================================================================
-- Проверка структуры: SELECT * по заполненным таблицам
-- (LIMIT 10, чтобы результат помещался на скриншот)
-- =====================================================================
SELECT * FROM book_list LIMIT 10;
SELECT * FROM clients   LIMIT 10;
SELECT * FROM loans   LIMIT 10;
SELECT * FROM book_ratings LIMIT 10;

-- Количество строк во всех таблицах
SELECT 'book_list' AS table_name, COUNT(*) AS rows_count FROM book_list
UNION ALL
SELECT 'clients', COUNT(*) FROM clients
UNION ALL
SELECT 'loans', COUNT(*) FROM loans
UNION ALL
SELECT 'book_ratings', COUNT(*) FROM book_ratings;

-- Проверка внешних ключей: пустой результат = все связи корректны
PRAGMA foreign_key_check;

-- Проверка связей через JOIN: кто какую книгу брал
SELECT a.loan_id,
       c.first_name || ' ' || c.last_name AS client,
       b.title,
       a.checkout_date, a.due_date, a.return_date, a.status, a.overdue_days
FROM loans AS a
JOIN clients   AS c ON c.client_id      = a.client_id
JOIN book_list AS b ON b.book_id = a.book_id
ORDER BY a.loan_id
LIMIT 10;

-- ---------------------------------------------------------------------
-- Жанры и авторы: SELECT * и проверки
-- ---------------------------------------------------------------------
SELECT * FROM genres;
SELECT * FROM authors      LIMIT 10;
SELECT * FROM book_genres  LIMIT 10;
SELECT * FROM book_genre_details LIMIT 10;
SELECT * FROM book_authors LIMIT 10;

-- Количество строк в новых таблицах
SELECT 'genres' AS table_name, COUNT(*) AS rows_count FROM genres
UNION ALL
SELECT 'authors', COUNT(*) FROM authors
UNION ALL
SELECT 'book_genres', COUNT(*) FROM book_genres
UNION ALL
SELECT 'book_authors', COUNT(*) FROM book_authors;

-- Книги с несколькими жанрами и книги с соавторами
SELECT book_id, title, authors, genres, genres_count
FROM book_info
WHERE genres LIKE '%,%' OR authors LIKE '%,%'
ORDER BY book_id
LIMIT 15;

-- Сколько книг имеют 1, 2, 3 жанра
SELECT genre_count, COUNT(*) AS books
FROM (SELECT book_id, COUNT(*) AS genre_count FROM book_genres GROUP BY book_id)
GROUP BY genre_count ORDER BY genre_count;

-- Сколько книг имеют 1, 2, 3 автора (автор + соавторы)
SELECT author_count, COUNT(*) AS books
FROM (SELECT book_id, COUNT(*) AS author_count FROM book_authors GROUP BY book_id)
GROUP BY author_count ORDER BY author_count;

-- Какие книги у каких авторов (топ-10 авторов по числу книг)
SELECT author,
       COUNT(*)                      AS books_total,
       SUM(role = 'author')          AS as_author,
       SUM(role = 'co-author')       AS as_co_author,
       GROUP_CONCAT(title, '; ')     AS titles
FROM author_books
GROUP BY author_id
ORDER BY books_total DESC, author
LIMIT 10;

-- Жанры по популярности (с учётом всех жанров книги, а не только основного)
SELECT g.genre_name, COUNT(*) AS books
FROM book_genres AS bg
JOIN genres AS g ON g.genre_id = bg.genre_id
GROUP BY g.genre_id
ORDER BY books DESC;

-- Проверки согласованности (пустой результат = всё корректно)
-- 1) у каждой книги ровно один основной жанр
SELECT b.book_id
FROM book_list AS b
LEFT JOIN book_genres AS bg ON bg.book_id = b.book_id AND bg.is_primary = 1
GROUP BY b.book_id
HAVING COUNT(bg.genre_id) <> 1;

-- 2) у каждой книги ровно один основной автор (role = 'author')
SELECT b.book_id
FROM book_list AS b
LEFT JOIN book_authors AS ba ON ba.book_id = b.book_id AND ba.role = 'author'
GROUP BY b.book_id
HAVING COUNT(ba.author_id) <> 1;


-- =====================================================================
-- ДЕЛО О ТАИНСТВЕННЫХ ДАННЫХ — проверки качества данных
-- =====================================================================

-- ---------------------------------------------------------------------
-- УЛИКА № 1: пропавшие значения
-- Различаем: NULL (значение отсутствует), '' (пустая строка),
-- 0 (числовой ноль), текстовые маркеры 'N/A', 'нет данных', '-', 'unknown'.
-- ---------------------------------------------------------------------

-- 1.1 book_list: NULL / пустые / "неизвестные" значения по полям
SELECT
    COUNT(*)                                                        AS total_rows,
    SUM(title IS NULL)                                              AS title_null,
    SUM(TRIM(CAST(title AS TEXT)) = '')                             AS title_empty,
    SUM(LOWER(TRIM(CAST(title AS TEXT))) IN ('n/a','na','нет данных','-','unknown','неизвестно')) AS title_marker,
    SUM(publication_year IS NULL)                                   AS year_null,
    SUM(publication_year = 0)                                       AS year_zero
FROM book_list;

-- 1.1а Авторы и жанры (после нормализации — в справочниках и связях):
-- пустые имена, маркеры «неизвестно», книги без автора или без жанра
SELECT
    (SELECT COUNT(*) FROM authors WHERE TRIM(first_name) = '' OR TRIM(last_name) = ''
        OR LOWER(TRIM(first_name)) IN ('n/a','na','нет данных','-','unknown','неизвестно')
        OR LOWER(TRIM(last_name))  IN ('n/a','na','нет данных','-','unknown','неизвестно')) AS bad_author_names,
    (SELECT COUNT(*) FROM genres WHERE TRIM(genre_name) = ''
        OR LOWER(TRIM(genre_name)) IN ('n/a','na','нет данных','-','unknown','неизвестно'))  AS bad_genre_names,
    (SELECT COUNT(*) FROM book_list WHERE book_id NOT IN (SELECT book_id FROM book_authors)) AS books_without_author,
    (SELECT COUNT(*) FROM book_list WHERE book_id NOT IN (SELECT book_id FROM book_genres))  AS books_without_genre;

-- 1.2 clients: NULL / пустые / "неизвестные" значения по полям
SELECT
    COUNT(*)                                                        AS total_rows,
    SUM(first_name IS NULL)                                         AS first_name_null,
    SUM(TRIM(first_name) = '')                                      AS first_name_empty,
    SUM(last_name IS NULL)                                          AS last_name_null,
    SUM(phone IS NULL)                                              AS phone_null,
    SUM(TRIM(phone) = '')                                           AS phone_empty,
    SUM(TRIM(last_name) = '')                                       AS last_name_empty,
    SUM(age_group IS NULL)                                          AS age_group_null,
    SUM(registration_date IS NULL)                                  AS reg_date_null,
    SUM(TRIM(registration_date) = '')                               AS reg_date_empty
FROM clients;

-- 1.3 loans: NULL / пустые значения по полям
-- (return_date IS NULL допустим для status = 'checked_out' — это не ошибка,
--  а значит "книга ещё не возвращена"; ошибка — NULL у уже возвращённых)
SELECT
    COUNT(*)                                                        AS total_rows,
    SUM(return_date IS NULL)                                        AS return_date_null,
    SUM(return_date IS NULL AND status = 'returned')                AS returned_without_date,
    SUM(return_date IS NOT NULL AND status = 'checked_out')         AS checked_out_with_date,
    SUM(TRIM(return_date) = '')                                     AS return_date_empty,
    SUM(overdue_days = 0)                                           AS overdue_zero
FROM loans;

-- 1.4 Команды фиксируют результат и решают, что делать с пропусками:
--   • оставить, если отсутствие значения содержательно важно
--     (return_date IS NULL у 'checked_out' — книга на руках);
--   • преобразовать по обоснованному правилу (пустая строка -> NULL);
--   • исправить по первоисточнику (returned без даты возврата — сверить с Excel).
-- Пример преобразования пустых строк в NULL (раскомментировать при необходимости):
-- UPDATE loans SET return_date = NULL WHERE TRIM(return_date) = '';

-- ---------------------------------------------------------------------
-- УЛИКА № 2: двойники и подозрительные записи
-- ---------------------------------------------------------------------

-- 2.1 Повторяющиеся идентификаторы (PRIMARY KEY не даст дублей, но проверим)
SELECT 'book_list' AS tbl, book_id AS id, COUNT(*) AS occurrences
FROM book_list GROUP BY book_id HAVING COUNT(*) > 1
UNION ALL
SELECT 'clients', client_id, COUNT(*) FROM clients GROUP BY client_id HAVING COUNT(*) > 1
UNION ALL
SELECT 'loans', loan_id, COUNT(*) FROM loans GROUP BY loan_id HAVING COUNT(*) > 1;

-- 2.2 Одинаковые записи, если ожидается уникальность:
--     книги с одинаковыми названием + автором + годом
SELECT title, author, publication_year, COUNT(*) AS occurrences
FROM book_catalog
GROUP BY title, author, publication_year
HAVING COUNT(*) > 1;

-- 2.3 Читатели-двойники: одинаковые имя + фамилия + дата регистрации
SELECT first_name, last_name, registration_date, COUNT(*) AS occurrences
FROM clients
GROUP BY first_name, last_name, registration_date
HAVING COUNT(*) > 1;

-- 2.4 Дубли выдач: один читатель взял одну книгу в один день несколько раз
SELECT client_id, book_id, checkout_date, COUNT(*) AS occurrences
FROM loans
GROUP BY client_id, book_id, checkout_date
HAVING COUNT(*) > 1;

-- 2.5 Неожиданные категории и разные варианты написания одного значения
-- (смотрим уникальные значения и их количество)
SELECT genre, COUNT(*) AS cnt FROM book_catalog GROUP BY genre ORDER BY cnt DESC;
SELECT age_group, COUNT(*) AS cnt FROM clients GROUP BY age_group ORDER BY cnt DESC;
SELECT status, COUNT(*) AS cnt FROM loans GROUP BY status ORDER BY cnt DESC;

-- Варианты написания, отличающиеся только регистром/пробелами:
SELECT LOWER(TRIM(genre_name)) AS normalized, COUNT(DISTINCT genre_name) AS variants
FROM genres
GROUP BY LOWER(TRIM(genre_name))
HAVING COUNT(DISTINCT genre_name) > 1;

-- 2.6 Границы числовых показателей (min / max / avg / count)
SELECT 'publication_year' AS metric,
       MIN(publication_year) AS min_value, MAX(publication_year) AS max_value,
       ROUND(AVG(publication_year), 2) AS avg_value, COUNT(publication_year) AS row_count
FROM book_list
UNION ALL
SELECT 'overdue_days',
       MIN(overdue_days), MAX(overdue_days),
       ROUND(AVG(overdue_days), 2), COUNT(overdue_days)
FROM loans
UNION ALL
SELECT 'loan_period_days (due - checkout)',
       MIN(julianday(due_date) - julianday(checkout_date)),
       MAX(julianday(due_date) - julianday(checkout_date)),
       ROUND(AVG(julianday(due_date) - julianday(checkout_date)), 2),
       COUNT(*)
FROM loans;

-- 2.7 Невозможные или сомнительные значения
-- книга издана в будущем
SELECT book_id, title, publication_year
FROM book_list
WHERE publication_year > CAST(strftime('%Y', 'now') AS INTEGER);

-- читатель зарегистрирован в будущем
SELECT client_id, first_name, last_name, registration_date
FROM clients
WHERE registration_date > DATE('now');

-- 2.8 Даты, которые не попадают в ожидаемый период
-- (период выдач берём из самих данных: смотрим границы и выбросы)
SELECT 'checkout_date' AS field, MIN(checkout_date) AS min_date, MAX(checkout_date) AS max_date FROM loans
UNION ALL
SELECT 'due_date', MIN(due_date), MAX(due_date) FROM loans
UNION ALL
SELECT 'return_date', MIN(return_date), MAX(return_date) FROM loans
UNION ALL
SELECT 'registration_date', MIN(registration_date), MAX(registration_date) FROM clients;

-- выдача раньше, чем читатель зарегистрировался
SELECT a.loan_id, a.client_id, a.checkout_date, c.registration_date
FROM loans AS a
JOIN clients AS c ON c.client_id = a.client_id
WHERE a.checkout_date < c.registration_date;

-- логические ошибки в датах / просрочке
SELECT loan_id, checkout_date, due_date, return_date, overdue_days
FROM loans
WHERE due_date < checkout_date
   OR (return_date IS NOT NULL AND return_date < checkout_date)
   OR (return_date IS NOT NULL AND return_date > due_date
       AND overdue_days <> CAST(julianday(return_date) - julianday(due_date) AS INTEGER))
   OR (return_date IS NOT NULL AND return_date <= due_date AND overdue_days <> 0);

-- ---------------------------------------------------------------------
-- УЛИКА № 3: записи без связей
-- ---------------------------------------------------------------------

-- 3.1 Проверка внешних ключей средствами SQLite
-- (возвращает строки, только если в таблицах с FK есть нарушения;
--  для loans результат должен быть пустым)
PRAGMA foreign_key_check;

-- Важно: FOREIGN KEY в схеме сам по себе не гарантирует, что проверка была
-- включена во время загрузки (PRAGMA foreign_keys = ON действует на соединение),
-- поэтому проверяем связи вручную. В исходных данных у 1812 выдач не было
-- читателя, у 1857 — книги; ID исправлены при загрузке, поэтому запросы
-- 3.2–3.4 теперь должны возвращать 0 нарушений:

-- 3.2 Выдачи, для которых не найден читатель
SELECT a.*
FROM loans AS a
LEFT JOIN clients AS c ON a.client_id = c.client_id
WHERE c.client_id IS NULL;

-- 3.3 Выдачи, для которых не найдена книга
SELECT a.*
FROM loans AS a
LEFT JOIN book_list AS b ON a.book_id = b.book_id
WHERE b.book_id IS NULL;

-- 3.4 Сводка: сколько связей нарушено
SELECT
    COUNT(*)                                        AS total_loans,
    SUM(c.client_id IS NULL)                               AS no_client,
    SUM(b.book_id IS NULL)                          AS no_book,
    SUM(c.client_id IS NULL OR b.book_id IS NULL)          AS broken_any,
    SUM(c.client_id IS NOT NULL AND b.book_id IS NOT NULL) AS valid_links
FROM loans AS a
LEFT JOIN clients   AS c ON a.client_id  = c.client_id
LEFT JOIN book_list AS b ON a.book_id = b.book_id;

-- 3.5 Читатели, у которых нет ни одной выдачи
SELECT c.*
FROM clients AS c
LEFT JOIN loans AS a ON a.client_id = c.client_id
WHERE a.loan_id IS NULL;

-- 3.6 Книги, которые ни разу не выдавались
SELECT b.*
FROM book_list AS b
LEFT JOIN loans AS a ON a.book_id = b.book_id
WHERE a.loan_id IS NULL;

-- ---------------------------------------------------------------------
-- Дополнительные проверки для оценок книг (book_ratings)
-- ---------------------------------------------------------------------

-- 1.5 Пропуски в оценках
SELECT COUNT(*)                     AS total_rows,
       SUM(rating IS NULL)          AS rating_null,
       SUM(comment IS NULL OR TRIM(comment) = '') AS comment_empty,
       SUM(rating_date IS NULL)     AS rating_date_null
FROM book_ratings;

-- 2.9 Двойники: один читатель оценил одну книгу несколько раз
SELECT client_id, book_id, COUNT(*) AS cnt
FROM book_ratings
GROUP BY client_id, book_id
HAVING COUNT(*) > 1;

-- 2.10 Границы оценок и распределение (ожидается шкала 0..10)
SELECT MIN(rating) AS min_rating, MAX(rating) AS max_rating,
       ROUND(AVG(rating), 2) AS avg_rating, COUNT(*) AS row_count
FROM book_ratings;

SELECT rating, COUNT(*) AS cnt FROM book_ratings GROUP BY rating ORDER BY rating;

-- 2.11 Оценка противоречит комментарию: высокий балл и негативный отзыв
SELECT rating_id, rating, comment
FROM book_ratings
WHERE (rating >= 8 AND (comment LIKE '%Не понравилось%' OR comment LIKE '%Скучно%'
                        OR comment LIKE '%Тяжело%' OR comment LIKE '%слаб%'))
   OR (rating <= 2 AND (comment LIKE '%Шедевр%' OR comment LIKE '%Отличная%'
                        OR comment LIKE '%Огонь%' OR comment LIKE '%Лучшее%'));

-- 2.12 Противоречие в доступности: в Excel у всех 1000 книг is_available = True,
-- а 68 книг по таблице выдач сейчас на руках (status = 'checked_out').
-- В БД это исправлено UPDATE после переноса выдач; проверка — должно быть 0:
SELECT COUNT(*) AS wrong_available
FROM book_list AS b
WHERE b.is_available = 1
  AND EXISTS (SELECT 1 FROM loans AS a
              WHERE a.book_id = b.book_id AND a.status = 'checked_out');

-- 3.7 Оценка без выдачи: читатель оценил книгу, которую не брал
SELECT r.rating_id, r.client_id, r.book_id
FROM book_ratings AS r
WHERE NOT EXISTS (SELECT 1 FROM loans AS a
                  WHERE a.client_id = r.client_id AND a.book_id = r.book_id);

-- 3.8 Оценка поставлена до возврата книги или к невозвращённой книге
SELECT r.rating_id, r.rating_date, a.return_date, a.status
FROM book_ratings AS r
JOIN loans AS a ON a.client_id = r.client_id AND a.book_id = r.book_id
WHERE a.status = 'checked_out'
   OR (r.rating_date < a.return_date
  AND NOT EXISTS (SELECT 1 FROM loans AS a2
                  WHERE a2.client_id = r.client_id AND a2.book_id = r.book_id
                    AND a2.return_date = r.rating_date));

-- 3.9 Возвращённые книги без оценки (не ошибка — оценка необязательна)
SELECT COUNT(*) AS returned_without_rating
FROM loans AS a
WHERE a.status = 'returned'
  AND NOT EXISTS (SELECT 1 FROM book_ratings AS r
                  WHERE r.client_id = a.client_id AND r.book_id = a.book_id);


-- =====================================================================
-- ПЕРВЫЕ АНАЛИТИЧЕСКИЕ ЗАПРОСЫ
-- =====================================================================
-- «Сегодня» для отчёта — последняя дата выдачи в данных (2024-12-30),
-- потому что данные исторические и реальная текущая дата не подходит.
--
-- АНАЛИТИЧЕСКИЙ ВОПРОС № 1:
-- «Кому можно выдать карту лояльности, а кому нельзя?»
-- Условия для карты:
--   • зарегистрирован в библиотеке больше 3 месяцев;
--   • взял не меньше 4 книг (среднее по библиотеке — 4 выдачи на читателя);
--   • ни одного дня просрочки за всё время.
-- Вопрос 1.2: «Кому нельзя выдавать книги?» — читателям с рейтингом < 5
--   (coefficient из представления client_rating, шкала 0–10).

-- ---------------------------------------------------------------------
-- Часть № 1. Базовая выборка
-- Читатели, зарегистрированные больше 3 месяцев назад
-- (первое условие карты лояльности; без SELECT *, с сортировкой).
-- ---------------------------------------------------------------------
SELECT client_id, first_name, last_name, age_group, registration_date
FROM clients
WHERE registration_date <= DATE((SELECT MAX(checkout_date) FROM loans), '-3 months')
ORDER BY registration_date
LIMIT 15;

-- Сколько читателей проходит по стажу (все 500 — последняя регистрация 2023-01-01)
SELECT COUNT(*) AS clients_over_3_months
FROM clients
WHERE registration_date <= DATE((SELECT MAX(checkout_date) FROM loans), '-3 months');

-- ---------------------------------------------------------------------
-- Часть № 2. Агрегирование
-- По каждому читателю: сколько книг взял, сколько раз и на сколько дней
-- опоздал (COUNT, SUM, MAX, MIN). Отбираем подходящих под карту.
-- ---------------------------------------------------------------------
SELECT client_id,
       COUNT(*)              AS books_taken,
       SUM(overdue_days > 0) AS late_returns,
       SUM(overdue_days)     AS overdue_days_total,
       MAX(overdue_days)     AS max_overdue,
       MIN(checkout_date)    AS first_checkout
FROM loans
GROUP BY client_id
HAVING COUNT(*) >= 4 AND SUM(overdue_days) = 0
ORDER BY books_taken DESC, client_id
LIMIT 15;

-- Общая сводка по читателям: сколько в среднем берут и опаздывают
SELECT COUNT(*)                          AS readers_with_loans,
       ROUND(AVG(books_taken), 2)        AS avg_books,
       MAX(books_taken)                  AS max_books,
       ROUND(AVG(overdue_days_total), 2) AS avg_overdue_days,
       SUM(overdue_days_total = 0)       AS readers_never_late
FROM (SELECT client_id, COUNT(*) AS books_taken, SUM(overdue_days) AS overdue_days_total
      FROM loans GROUP BY client_id);

-- ---------------------------------------------------------------------
-- Часть № 3. Соединение таблиц — финальный запрос вопроса № 1
-- Список читателей, которым можно выдать карту лояльности
-- (clients + loans: стаж + количество книг + отсутствие просрочек).
-- ---------------------------------------------------------------------
SELECT c.client_id,
       c.first_name || ' ' || c.last_name AS reader,
       c.age_group,
       c.registration_date,
       COUNT(a.loan_id)                AS books_taken,
       SUM(a.overdue_days)                AS overdue_days_total
FROM clients AS c
JOIN loans AS a ON a.client_id = c.client_id
WHERE c.registration_date <= DATE((SELECT MAX(checkout_date) FROM loans), '-3 months')
GROUP BY c.client_id
HAVING COUNT(a.loan_id) >= 4 AND SUM(a.overdue_days) = 0
ORDER BY books_taken DESC, c.client_id;

-- Сколько читателей получает карту, по возрастным группам
SELECT c.age_group, COUNT(*) AS loyalty_cards
FROM clients AS c
WHERE (SELECT COUNT(*) FROM loans AS a WHERE a.client_id = c.client_id) >= 4
  AND (SELECT SUM(overdue_days) FROM loans AS a WHERE a.client_id = c.client_id) = 0
  AND c.registration_date <= DATE((SELECT MAX(checkout_date) FROM loans), '-3 months')
GROUP BY c.age_group
ORDER BY loyalty_cards DESC;

-- ---------------------------------------------------------------------
-- Вопрос 1.2. Кому нельзя выдавать книги? (рейтинг < 5)
-- client_rating соединяет clients и loans и считает coefficient.
-- ---------------------------------------------------------------------
SELECT client_id,
       first_name || ' ' || last_name AS reader,
       age_group,
       books_taken,
       arrears_count,
       late_share,
       coefficient
FROM client_rating
WHERE coefficient < 5
ORDER BY coefficient, arrears_count DESC;

-- Итог вопроса № 1 одной таблицей: кто в какую группу попал
SELECT CASE
           WHEN r.coefficient < 5 THEN '3. Нельзя выдавать книги (рейтинг < 5)'
           WHEN r.books_taken >= 4 AND r.overdue_days_total = 0
                AND r.registration_date <= DATE((SELECT MAX(checkout_date) FROM loans), '-3 months')
                THEN '1. Можно выдать карту лояльности'
           ELSE '2. Обычный читатель (карты нет, книги выдавать можно)'
       END AS decision,
       COUNT(*) AS readers_count
FROM client_rating AS r
GROUP BY decision
ORDER BY decision;


-- АНАЛИТИЧЕСКИЙ ВОПРОС № 2:
-- «Что нужно списать, а что нужно докупить?»
--   • Докупить — книги, которые дольше всего находятся на руках
--     и у которых в среднем много дней просрочки (на них очередь).
--   • Списать — книги, которые не пользуются популярностью
--     (0–1 выдача) и со старой датой выпуска (раньше 1980 года).
-- Используем: HAVING, подзапрос, EXISTS / NOT EXISTS, CASE.

-- 2.1 HAVING + подзапрос: книги, которые держат на руках дольше среднего
--     по библиотеке (дни на руках = возврат − выдача; если книга ещё
--     у читателя — считаем до даты отчёта). Брались хотя бы 3 раза.
SELECT b.book_id, b.title, b.author,
       COUNT(*) AS loans,
       ROUND(AVG(julianday(COALESCE(a.return_date, (SELECT MAX(checkout_date) FROM loans)))
                 - julianday(a.checkout_date)), 1) AS avg_days_on_hands,
       ROUND(AVG(a.overdue_days), 2) AS avg_overdue_days
FROM loans   AS a
JOIN book_catalog AS b ON b.book_id = a.book_id
GROUP BY b.book_id
HAVING COUNT(*) >= 3
   AND AVG(julianday(COALESCE(a.return_date, (SELECT MAX(checkout_date) FROM loans)))
           - julianday(a.checkout_date))
       > (SELECT AVG(julianday(COALESCE(return_date, (SELECT MAX(checkout_date) FROM loans)))
                     - julianday(checkout_date))
          FROM loans)
ORDER BY avg_days_on_hands DESC, b.book_id
LIMIT 15;

-- 2.2 Подзапрос: книги, у которых средняя просрочка выше средней
--     по библиотеке (ещё один признак, что книги не хватает)
SELECT b.book_id, b.title, b.author, t.loans, t.avg_overdue_days
FROM book_catalog AS b
JOIN (SELECT book_id, COUNT(*) AS loans, ROUND(AVG(overdue_days), 2) AS avg_overdue_days
      FROM loans GROUP BY book_id) AS t
  ON t.book_id = b.book_id
WHERE t.loans >= 3
  AND t.avg_overdue_days > (SELECT AVG(overdue_days) FROM loans)
ORDER BY t.avg_overdue_days DESC, t.loans DESC
LIMIT 15;

-- 2.3 EXISTS: популярные книги, которые прямо сейчас на руках —
--     другой читатель взять их не может
SELECT b.book_id, b.title, b.author,
       (SELECT COUNT(*) FROM loans AS a WHERE a.book_id = b.book_id) AS loans
FROM book_catalog AS b
WHERE EXISTS (SELECT 1 FROM loans AS a
              WHERE a.book_id = b.book_id AND a.status = 'checked_out')
  AND (SELECT COUNT(*) FROM loans AS a WHERE a.book_id = b.book_id) >= 3
ORDER BY loans DESC;

-- 2.4 NOT EXISTS: кандидаты на списание — старые книги (до 1980),
--     которые ни разу не выдавались
SELECT b.book_id, b.title, b.author, b.genre, b.publication_year
FROM book_catalog AS b
WHERE b.publication_year < 1980
  AND NOT EXISTS (SELECT 1 FROM loans AS a WHERE a.book_id = b.book_id)
ORDER BY b.publication_year;

-- 2.5 CASE — итоговый запрос: решение по каждой книге
--     «Докупить» / «Списать» / «Оставить», с рейтингом книги
WITH book_stats AS (
    SELECT b.book_id, b.title, b.author, b.genre, b.publication_year,
           COUNT(a.loan_id) AS loans,
           AVG(julianday(COALESCE(a.return_date, (SELECT MAX(checkout_date) FROM loans)))
               - julianday(a.checkout_date)) AS avg_days_on_hands,
           AVG(a.overdue_days) AS avg_overdue_days
    FROM book_catalog AS b
    LEFT JOIN loans AS a ON a.book_id = b.book_id
    GROUP BY b.book_id
),
library AS (
    SELECT AVG(julianday(COALESCE(return_date, (SELECT MAX(checkout_date) FROM loans)))
               - julianday(checkout_date)) AS avg_days,
           AVG(overdue_days) AS avg_overdue
    FROM loans
)
SELECT s.book_id, s.title, s.author, s.publication_year, s.loans,
       ROUND(s.avg_days_on_hands, 1) AS avg_days_on_hands,
       ROUND(s.avg_overdue_days, 2)  AS avg_overdue_days,
       r.avg_rating,
       CASE
           WHEN s.loans >= 3
                AND s.avg_days_on_hands > l.avg_days
                AND s.avg_overdue_days  > l.avg_overdue  THEN 'Докупить'
           WHEN s.loans <= 1 AND s.publication_year < 1980 THEN 'Списать'
           ELSE 'Оставить'
       END AS decision
FROM book_stats AS s
CROSS JOIN library AS l
LEFT JOIN book_rating AS r ON r.book_id = s.book_id
WHERE CASE
          WHEN s.loans >= 3 AND s.avg_days_on_hands > l.avg_days
               AND s.avg_overdue_days > l.avg_overdue THEN 1
          WHEN s.loans <= 1 AND s.publication_year < 1980 THEN 1
          ELSE 0
      END = 1
ORDER BY decision, s.avg_overdue_days DESC, s.publication_year;

-- Сводка по решению вопроса № 2
WITH book_stats AS (
    SELECT b.book_id, b.publication_year,
           COUNT(a.loan_id) AS loans,
           AVG(julianday(COALESCE(a.return_date, (SELECT MAX(checkout_date) FROM loans)))
               - julianday(a.checkout_date)) AS avg_days_on_hands,
           AVG(a.overdue_days) AS avg_overdue_days
    FROM book_catalog AS b
    LEFT JOIN loans AS a ON a.book_id = b.book_id
    GROUP BY b.book_id
),
library AS (
    SELECT AVG(julianday(COALESCE(return_date, (SELECT MAX(checkout_date) FROM loans)))
               - julianday(checkout_date)) AS avg_days,
           AVG(overdue_days) AS avg_overdue
    FROM loans
)
SELECT CASE
           WHEN s.loans >= 3 AND s.avg_days_on_hands > l.avg_days
                AND s.avg_overdue_days > l.avg_overdue THEN 'Докупить'
           WHEN s.loans <= 1 AND s.publication_year < 1980 THEN 'Списать'
           ELSE 'Оставить'
       END AS decision,
       COUNT(*) AS books_count
FROM book_stats AS s
CROSS JOIN library AS l
GROUP BY decision
ORDER BY decision;

