-- Вопрос № 1. Карту лояльности можно выдать 147 читателям: все
--   зарегистрированы больше 3 месяцев, взяли 4 книги и больше и ни разу
--   не опоздали (adult 78, senior 28, child 23, teen 18).
--   Лидеры: Cindy Sanders, Michelle Smith, Crystal Taylor — по 10 книг.
-- Вопрос 1.2. Нельзя выдавать книги 62 читателям с рейтингом ниже 5:
--   это те, кто брал мало книг и часто возвращал их с опозданием
--   (хуже всех — 0,4: взяли одну книгу и сдали её с просрочкой).
--   Остальные 282 читателя — обычные: карты нет, но книги выдавать можно.
-- Вопрос № 2. Докупить стоит 65 книг: их берут 3 раза и больше,
--   держат дольше среднего и в среднем сильнее опаздывают с возвратом
--   (первая в списке — Harry Potter and the Sorcerer's Stone Vol. 8:
--   в среднем 36 дней на руках и 9 дней просрочки).
--   Списать можно 159 книг: изданы до 1980 года и брались не больше
--   одного раза (67 из них не выдавались ни разу).
--   Остальные 776 книг оставляем.
